import os

from app.db_url import load_env_files


def test_env_local_loads_without_overriding_process_env(monkeypatch, tmp_path):
    monkeypatch.delenv("RT_TEST_FILE_ONLY", raising=False)
    monkeypatch.setenv("RT_TEST_EXISTING", "from-process")
    (tmp_path / ".env.local").write_text(
        '# generated by neon deploy\nRT_TEST_FILE_ONLY="file value"\nRT_TEST_EXISTING=from-file\n',
        encoding="utf-8",
    )
    (tmp_path / ".env").write_text("RT_TEST_FILE_ONLY=from-env\n", encoding="utf-8")

    load_env_files(tmp_path)

    assert os.environ["RT_TEST_FILE_ONLY"] == "file value"
    assert os.environ["RT_TEST_EXISTING"] == "from-process"


def test_missing_env_files_are_ignored(monkeypatch, tmp_path):
    monkeypatch.delenv("RT_TEST_ABSENT", raising=False)

    load_env_files(tmp_path)

    assert "RT_TEST_ABSENT" not in os.environ
